traces.query:
PREFIX net: <http://example.org/network#>
SELECT ?alarm ?label WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice ?dev ;
         rdfs:label ?label .
  ?dev a net:NetworkDevice ;
       rdfs:label "Edge Firewall FW1" .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(?alarm) AS ?criticalAlarmCount)
WHERE {
  ?alarm a net:Alarm ;
         net:hasSeverity "CRITICAL" .
}

PREFIX net: <http://example.org/network#>
SELECT ?alarm ?label WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice net:Router_Core ;
         rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>
SELECT ?severity WHERE {
  net:Alarm_PacketDrop net:hasSeverity ?severity .
}

PREFIX net: <http://example.org/network#>
SELECT ?device (COUNT(?alarm) AS ?alarmCount)
WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice ?device .
}
GROUP BY ?device
ORDER BY DESC(?alarmCount)
LIMIT 1

PREFIX net: <http://example.org/network#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?alarm ?time WHERE {
  ?alarm a net:Alarm ;
         net:triggeredAt ?time .
}
ORDER BY ASC(?time)
LIMIT 1

PREFIX net: <http://example.org/network#>
SELECT ?mitreId WHERE {
  net:Incident_DDoS net:classifiedAs ?pattern .
  ?pattern net:mitreId ?mitreId .
}

PREFIX net: <http://example.org/network#>

SELECT ?deviceType
WHERE {
  net:Server_Web net:deviceType ?deviceType .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(?alarm) AS ?alarmCount)
WHERE {
  net:Incident_DDoS net:composedOf ?alarm .
}

PREFIX net: <http://example.org/network#>
SELECT ?alarm WHERE {
  ?alarm a net:Alarm ;
         net:hasSeverity "HIGH" .
}

PREFIX net: <http://example.org/network#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?alarm ?time
WHERE {
  ?alarm a net:Alarm ;
         net:triggeredAt ?time .
  FILTER ( ?time > "2026-06-02T14:01:00"^^xsd:dateTime )
}

PREFIX net: <http://example.org/network#>
SELECT ?incident ?rootAlarm WHERE {
  ?incident a net:Incident ;
            net:composedOf ?alarm .
  FILTER NOT EXISTS {
    ?otherAlarm net:causallyLinkedTo ?alarm .
    ?incident net:composedOf ?otherAlarm .
  }
  BIND(?alarm AS ?rootAlarm)
}

PREFIX net: <http://example.org/network#>
SELECT ?causeLabel WHERE {
  net:Alarm_WebTimeout net:causallyLinkedTo ?cause .
  ?cause rdfs:label ?causeLabel .
}

PREFIX net: <http://example.org/network#>
SELECT ?causeLabel WHERE {
  ?cause net:causedBy net:Alarm_Latency .
  ?cause rdfs:label ?causeLabel .
}

PREFIX net: <http://example.org/network#>
SELECT ?downstreamAlarm ?label
WHERE {
  net:Alarm_FirewallSpike net:causallyLinkedTo ?downstreamAlarm .
  ?downstreamAlarm rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>
SELECT ?intermediateAlarm ?type ?severity WHERE {
  net:Alarm_FirewallSpike net:causallyLinkedTo+ ?intermediateAlarm .
  ?intermediateAlarm net:causallyLinkedTo+ net:Alarm_WebTimeout .
  FILTER(?intermediateAlarm != net:Alarm_FirewallSpike && ?intermediateAlarm != net:Alarm_WebTimeout)
  OPTIONAL { ?intermediateAlarm net:alarmType ?type . }
  OPTIONAL { ?intermediateAlarm net:hasSeverity ?severity . }
}

PREFIX net: <http://example.org/network#>

ASK {
  net:Alarm_CPU (net:causallyLinkedTo|net:causedBy)+ net:Alarm_WebTimeout .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(*) AS ?linkCount) WHERE {
  net:Alarm_Latency net:causallyLinkedTo+ net:Alarm_WebTimeout .
}

PREFIX net: <http://example.org/network#>

SELECT ?alarm ?device
WHERE {
  ?alarm a net:Alarm .
  OPTIONAL { ?alarm net:affectsDevice ?device . }
  FILTER NOT EXISTS { ?otherAlarm net:causallyLinkedTo ?alarm . }
}

PREFIX net: <http://example.org/network#>

SELECT ?relation
WHERE {
  VALUES ?a { net:Alarm_Latency net:Alarm_PacketDrop }
  VALUES ?b { net:Alarm_Latency net:Alarm_PacketDrop }
  FILTER(?a != ?b)
  { ?a net:causedBy ?b } UNION
  { ?b net:causedBy ?a } UNION
  { ?a net:causallyLinkedTo ?b } UNION
  { ?b net:causallyLinkedTo ?a }
  BIND("causal link exists" AS ?relation)
} LIMIT 1

PREFIX net: <http://example.org/network#>

SELECT ?alarm
WHERE {
  ?alarm net:correlatedWith net:Alarm_PacketDrop .
  FILTER NOT EXISTS { ?alarm net:causallyLinkedTo net:Alarm_PacketDrop }
  FILTER NOT EXISTS { net:Alarm_PacketDrop net:causallyLinkedTo ?alarm }
}

PREFIX net: <http://example.org/network#>
SELECT ?alarm ?label WHERE {
  net:Alarm_FirewallSpike net:causallyLinkedTo ?alarm .
  ?alarm rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>

SELECT ?avoidedAlarm ?avoidedLabel WHERE {
  net:Alarm_CPU net:causallyLinkedTo ?avoidedAlarm .
  ?avoidedAlarm rdfs:label ?avoidedLabel .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(DISTINCT ?affectedAlarm) AS ?preventedAlarms)
WHERE {
  net:Alarm_PacketDrop net:causallyLinkedTo ?affectedAlarm .
}

PREFIX net: <http://example.org/network#>

SELECT ?otherAlarm ?type ?severity ?time
WHERE {
  net:Incident_DDoS net:composedOf ?otherAlarm .
  FILTER(?otherAlarm != net:Alarm_CPU)
  OPTIONAL { ?otherAlarm net:alarmType ?type . }
  OPTIONAL { ?otherAlarm net:hasSeverity ?severity . }
  OPTIONAL { ?otherAlarm net:triggeredAt ?time . }
  FILTER NOT EXISTS {
    net:Alarm_CPU net:causallyLinkedTo ?otherAlarm .
  }
}

PREFIX net: <http://example.org/network#>

ASK {
  net:Alarm_Latency net:causallyLinkedTo net:Alarm_WebTimeout .
}
